arguments.cmd:
cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Reinvention at Global Scale</title>
  <style>
    :root {
      --bg: oklch(13% 0.01 260);
      --surface: oklch(18% 0.01 260);
      --surface-2: oklch(22% 0.015 260);
      --text: oklch(96% 0.01 260);
      --muted: oklch(75% 0.02 260);
      --line: oklch(35% 0.015 260);
      --accent-blue: oklch(68% 0.2 250);
      --accent-amber: oklch(78% 0.16 70);
      --max: 1200px;
      --radius: 18px;
      --space: clamp(1rem, 2vw, 1.5rem);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, "Neue Haas Grotesk Text Pro", "SF Pro Text", system-ui, -apple-system, Segoe UI, sans-serif;
      background: radial-gradient(1200px 700px at 80% -10%, oklch(25% 0.06 250 / 0.25), transparent 55%), var(--bg);
      color: var(--text);
      line-height: 1.45;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; width: 100%; height: 100%; object-fit: cover; }

    .container { width: min(var(--max), 92vw); margin: 0 auto; }
    section { padding: clamp(3rem, 6vw, 6rem) 0; }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(10px);
      background: oklch(13% 0.01 260 / 0.75);
      border-bottom: 1px solid var(--line);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 1rem;
    }

    .brand { font-weight: 700; letter-spacing: .02em; font-size: 1.05rem; }
    .brand span { color: var(--accent-blue); }

    .nav-links {
      display: flex;
      gap: 1.15rem;
      align-items: center;
      font-size: .95rem;
      color: var(--muted);
    }
    .nav-links a:hover { color: var(--text); }

    .lang-wrap { position: relative; }
    .lang-btn {
      background: transparent;
      color: var(--text);
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: .45rem .8rem;
      cursor: pointer;
    }
    .lang-menu {
      position: absolute;
      right: 0;
      margin-top: .5rem;
      width: 170px;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 12px;
      display: none;
      overflow: hidden;
    }
    .lang-menu.open { display: block; }
    .lang-menu button {
      width: 100%;
      text-align: left;
      border: 0;
      background: transparent;
      color: var(--text);
      padding: .65rem .8rem;
      cursor: pointer;
    }
    .lang-menu button:hover { background: var(--surface-2); }

    .menu-toggle {
      display: none;
      background: transparent;
      color: var(--text);
      border: 1px solid var(--line);
      border-radius: 10px;
      padding: .35rem .6rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.25fr .95fr;
      gap: clamp(1.2rem, 2.8vw, 2rem);
      align-items: stretch;
    }

    .eyebrow {
      color: var(--accent-amber);
      text-transform: uppercase;
      letter-spacing: .15em;
      font-size: .78rem;
      margin-bottom: 1rem;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.25rem, 8vw, 5.2rem);
      line-height: .94;
      letter-spacing: -0.02em;
    }

    .hero-copy p {
      margin-top: 1.25rem;
      max-width: 60ch;
      color: var(--muted);
      font-size: clamp(1rem, 1.8vw, 1.1rem);
    }

    .hero-actions { margin-top: 1.8rem; display: flex; gap: .75rem; flex-wrap: wrap; }
    .btn {
      border: 1px solid var(--line);
      border-radius: 999px;
      padding: .65rem 1.05rem;
      display: inline-flex;
      align-items: center;
      gap: .4rem;
      cursor: pointer;
      background: transparent;
      color: var(--text);
    }
    .btn.primary {
      background: linear-gradient(90deg, var(--accent-blue), oklch(62% 0.22 282));
      border-color: transparent;
      color: #fff;
    }

    .hero-carousel {
      background: linear-gradient(160deg, oklch(25% 0.05 250 / .35), var(--surface));
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      min-height: 430px;
    }

    .hero-track {
      display: flex;
      flex: 1;
      transition: transform .55s ease;
      touch-action: pan-y;
    }
    .hero-slide {
      min-width: 100%;
      padding: 1.2rem;
      display: grid;
      grid-template-rows: 180px auto;
      gap: .9rem;
    }

    .hero-media {
      border-radius: 12px;
      overflow: hidden;
      position: relative;
    }

    .hero-meta h3 { margin: 0 0 .5rem; font-size: 1.2rem; }
    .hero-meta p { margin: 0; color: var(--muted); }

    .carousel-controls {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: .9rem 1.1rem 1.1rem;
      border-top: 1px solid var(--line);
    }
    .dots { display: flex; gap: .4rem; }
    .dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: oklch(45% 0.02 260);
      border: 0;
      cursor: pointer;
    }
    .dot.active { background: var(--accent-amber); }

    .controls button {
      border: 1px solid var(--line);
      background: transparent;
      color: var(--text);
      border-radius: 8px;
      padding: .32rem .65rem;
      cursor: pointer;
      margin-left: .35rem;
    }

    .section-head { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-bottom: 1.2rem; }
    h2 { margin: 0; font-size: clamp(1.6rem, 4vw, 2.5rem); letter-spacing: -0.02em; }

    .region-tabs { display: flex; gap: .5rem; flex-wrap: wrap; }
    .region-tab {
      border: 1px solid var(--line);
      background: transparent;
      color: var(--muted);
      border-radius: 999px;
      padding: .45rem .8rem;
      cursor: pointer;
    }
    .region-tab.active {
      color: #fff;
      border-color: oklch(65% 0.2 250);
      box-shadow: inset 0 0 0 1px oklch(65% 0.2 250 / .45);
    }

    .team-wrap { position: relative; }
    .team-track {
      display: flex;
      gap: .9rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: .5rem;
      -webkit-overflow-scrolling: touch;
    }
    .team-card {
      flex: 0 0 clamp(250px, 32vw, 340px);
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 16px;
      overflow: hidden;
      scroll-snap-align: start;
    }
    .team-photo { aspect-ratio: 4 / 3; }
    .team-content { padding: .9rem; }
    .team-content blockquote {
      margin: 0 0 .7rem;
      color: var(--text);
      font-size: .97rem;
      line-height: 1.5;
    }
    .team-content p { margin: .2rem 0; color: var(--muted); font-size: .92rem; }
    .team-content a { color: var(--accent-amber); font-size: .9rem; }

    .scroll-row {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(260px, 350px);
      gap: .95rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      padding-bottom: .6rem;
    }
    .work-card, .insight-card {
      scroll-snap-align: start;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 16px;
      overflow: hidden;
    }
    .card-media { aspect-ratio: 16 / 10; }
    .card-body { padding: .95rem; }
    .card-body h3 { margin: 0 0 .35rem; font-size: 1.05rem; }
    .card-body p { margin: 0; color: var(--muted); font-size: .93rem; }

    .cta {
      border: 1px solid var(--line);
      background: linear-gradient(120deg, oklch(20% 0.03 250), oklch(26% 0.08 280 / .45));
      border-radius: 20px;
      padding: clamp(1.2rem, 4vw, 2.2rem);
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .how-grid, .principles-grid {
      display: grid;
      gap: .9rem;
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }
    .panel {
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 14px;
      padding: 1rem;
    }
    .panel h3 { margin-top: 0; font-size: 1rem; }
    .panel p { color: var(--muted); margin-bottom: 0; font-size: .92rem; }

    .footer {
      border-top: 1px solid var(--line);
      padding: 2.2rem 0;
      color: var(--muted);
      display: grid;
      gap: .65rem;
    }

    .cookie {
      position: fixed;
      left: 50%;
      bottom: 1rem;
      transform: translateX(-50%);
      width: min(860px, 92vw);
      background: oklch(18% 0.01 260 / .95);
      border: 1px solid var(--line);
      border-radius: 12px;
      padding: .85rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: .8rem;
      z-index: 100;
    }
    .cookie p { margin: 0; color: var(--muted); font-size: .9rem; }
    .cookie-actions { display: flex; gap: .45rem; flex-wrap: wrap; }
    .cookie.hidden { display: none; }

    @media (max-width: 980px) {
      .hero-grid { grid-template-columns: 1fr; }
      .how-grid, .principles-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .nav-links {
        position: fixed;
        inset: 76px 0 auto 0;
        background: oklch(12% 0.01 260 / 0.98);
        border-bottom: 1px solid var(--line);
        flex-direction: column;
        align-items: flex-start;
        padding: 1rem 4vw;
        display: none;
      }
      .nav-links.open { display: flex; }
      .menu-toggle { display: inline-flex; }
    }

    @media (max-width: 640px) {
      section { padding: 2.6rem 0; }
      .how-grid, .principles-grid { grid-template-columns: 1fr; }
      .cookie { flex-direction: column; align-items: flex-start; }
      .hero-slide { grid-template-rows: 145px auto; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container nav">
      <div class="brand">LEAP <span>STUDIO</span></div>
      <button class="menu-toggle" id="menuToggle" aria-label="Toggle menu">Menu</button>
      <nav class="nav-links" id="navLinks">
        <a href="#latest-insights">Insights</a>
        <a href="#work-showcase">Work</a>
        <a href="#how-we-work">Services</a>
        <a href="#team-carousel">Culture</a>
        <a href="#cta-banner">Make Your Mark</a>
        <a href="#footer">Contact Us</a>
        <div class="lang-wrap">
          <button class="lang-btn" id="langBtn">Global EN ▾</button>
          <div class="lang-menu" id="langMenu">
            <button data-lang="Global EN">Global EN</button>
            <button data-lang="France FR">France FR</button>
            <button data-lang="China CN">China CN</button>
          </div>
        </div>
      </nav>
    </div>
  </header>

  <main>
    <section id="hero" class="container">
      <div class="hero-grid">
        <div class="hero-copy">
          <div class="eyebrow">Reinvention & Experience Partner</div>
          <h1>We design what enterprise growth feels like.</h1>
          <p>Leap Studio combines strategic rigor, creative direction, and emerging technology to help global brands reimagine customer experiences at scale.</p>
          <div class="hero-actions">
            <a class="btn primary" href="#work-showcase">Explore Work</a>
            <a class="btn" href="#cta-banner">Start a Conversation</a>
          </div>
        </div>

        <div class="hero-carousel" aria-label="Featured content carousel">
          <div class="hero-track" id="heroTrack"></div>
          <div class="carousel-controls">
            <div class="dots" id="heroDots"></div>
            <div class="controls">
              <button id="heroPrev" aria-label="Previous hero slide">←</button>
              <button id="heroNext" aria-label="Next hero slide">→</button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section id="team-carousel" class="container">
      <div class="section-head">
        <h2>Global studios, one creative standard.</h2>
        <div class="region-tabs" id="regionTabs"></div>
      </div>
      <div class="team-wrap">
        <div class="team-track" id="teamTrack" aria-label="Team member carousel"></div>
      </div>
    </section>

    <section id="work-showcase" class="container">
      <div class="section-head">
        <h2>Selected client work</h2>
      </div>
      <div class="scroll-row" id="workRow"></div>
    </section>

    <section id="cta-banner" class="container">
      <div class="cta">
        <div>
          <h2 style="margin:0 0 .4rem;">Ready to leap forward?</h2>
          <p style="margin:0;color:var(--muted);">Partner with Leap Studio to align ambition, brand, and execution across every market.</p>
        </div>
        <a href="#footer" class="btn primary">Contact the Team</a>
      </div>
    </section>

    <section id="how-we-work" class="container">
      <div class="section-head"><h2>How we work</h2></div>
      <div class="how-grid" id="howGrid"></div>
    </section>

    <section id="latest-insights" class="container">
      <div class="section-head"><h2>Latest insights</h2></div>
      <div class="scroll-row" id="insightsRow"></div>
    </section>

    <section id="principles" class="container">
      <div class="section-head"><h2>Our principles</h2></div>
      <div class="principles-grid" id="principlesGrid"></div>
    </section>
  </main>

  <footer id="footer" class="container footer">
    <div style="font-weight:600; color:var(--text)">Leap Studio</div>
    <div>Studios: New York · San Francisco · London · Munich · Singapore · Melbourne</div>
    <div>© 2026 Leap Studio. Reinvention at global scale.</div>
  </footer>

  <div class="cookie" id="cookieBanner" role="dialog" aria-label="Cookie consent">
    <p>We use cookies to improve performance, personalize content, and understand usage across global markets.</p>
    <div class="cookie-actions">
      <button class="btn" id="declineCookies">Decline all</button>
      <button class="btn" id="manageCookies">Manage settings</button>
      <button class="btn primary" id="acceptCookies">Accept all</button>
    </div>
  </div>

  <script>
    const heroItems = [
      {
        title: "When Human Connection Meets AI",
        desc: "New report: balancing machine intelligence with deeply human brand experiences.",
        image: "https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=1400&q=70"
      },
      {
        title: "Reimagining Luxury Craftsmanship",
        desc: "How digital storytelling elevated heritage and unlocked a new generation of clients.",
        image: "https://images.unsplash.com/photo-1456324504439-367cee3b3c32?auto=format&fit=crop&w=1400&q=70"
      },
      {
        title: "Podcast: Writing the Future of AI",
        desc: "A leadership dialogue on trust, velocity, and practical transformation in the enterprise.",
        image: "https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1400&q=70"
      }
    ];

    const teamData = {
      "North America": [
        { name: "Maya R.", title: "Executive Creative Director", office: "New York", quote: "We turn complexity into clarity brands can act on.", image: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=70" },
        { name: "Jordan L.", title: "Head of Experience Strategy", office: "San Francisco", quote: "Great customer journeys are designed, not discovered by accident.", image: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=900&q=70" }
      ],
      "Asia": [
        { name: "Aiko T.", title: "Design Innovation Lead", office: "Singapore", quote: "Speed matters, but relevance in local context matters more.", image: "https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?auto=format&fit=crop&w=900&q=70" },
        { name: "Ravi K.", title: "Service Design Director", office: "Singapore", quote: "We design ecosystems, not isolated touchpoints.", image: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=70" }
      ],
      "Europe": [
        { name: "Elena V.", title: "Principal Brand Strategist", office: "London", quote: "Enduring brands reinvent without losing their soul.", image: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=900&q=70" },
        { name: "Lukas M.", title: "Transformation Partner", office: "Munich", quote: "From boardroom intent to frontline behavior—that is our craft.", image: "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=900&q=70" }
      ],
      "Oceania": [
        { name: "Sienna P.", title: "Studio Director", office: "Melbourne", quote: "Bold ideas earn trust when they solve real constraints.", image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=900&q=70" },
        { name: "Noah C.", title: "Head of Product Experience", office: "Melbourne", quote: "We bridge visionary strategy with practical delivery.", image: "https://images.unsplash.com/photo-1506277886164-e25aa3f4ef7f?auto=format&fit=crop&w=900&q=70" }
      ]
    };

    const workProjects = [
      "Creating Consumer Insights at Scale",
      "Deepening Customer Engagement",
      "Harnessing Data for Leaner and Greener Future of Mobility",
      "Modernizing the Point-of-Sale Experience",
      "Reimagining Luxury Craftsmanship",
      "Helping Healthier Habits Stick"
    ];

    const insights = [
      "When Human Connection Meets AI",
      "Writing the Future of AI",
      "Amplifying Clinical Care with AI",
      "The Future of Customer Experience",
      "Next-Gen Contact Centers: Powered by AI",
      "From Complexity to Clarity"
    ];

    const principles = [
      "Challenge the status quo",
      "Fuse art & science to make ideas real",
      "Create a lasting impact at global scale",
      "Regenerate systems & communities"
    ];

    const howWeWork = [
      { t: "Discover", d: "Understand ambition, constraints, and moments that matter most." },
      { t: "Define", d: "Shape clear opportunity spaces and executable design principles." },
      { t: "Design", d: "Prototype high-fidelity experiences that align brand and business." },
      { t: "Deliver", d: "Scale globally with measurable outcomes and cultural relevance." }
    ];

    const heroTrack = document.getElementById('heroTrack');
    const heroDots = document.getElementById('heroDots');
    let heroIndex = 0;
    let heroInterval;

    heroItems.forEach((item, index) => {
      const slide = document.createElement('article');
      slide.className = 'hero-slide';
      slide.innerHTML = `
        <div class="hero-media"><img src="${item.image}" alt="${item.title}" /></div>
        <div class="hero-meta">
          <h3>${item.title}</h3>
          <p>${item.desc}</p>
        </div>
      `;
      heroTrack.appendChild(slide);

      const dot = document.createElement('button');
      dot.className = 'dot' + (index === 0 ? ' active' : '');
      dot.addEventListener('click', () => setHero(index));
      heroDots.appendChild(dot);
    });

    function setHero(idx) {
      heroIndex = (idx + heroItems.length) % heroItems.length;
      heroTrack.style.transform = `translateX(-${heroIndex * 100}%)`;
      [...heroDots.children].forEach((d, i) => d.classList.toggle('active', i === heroIndex));
    }

    function nextHero() { setHero(heroIndex + 1); }
    function startHeroAuto() {
      clearInterval(heroInterval);
      heroInterval = setInterval(nextHero, 4600);
    }

    document.getElementById('heroPrev').addEventListener('click', () => { setHero(heroIndex - 1); startHeroAuto(); });
    document.getElementById('heroNext').addEventListener('click', () => { setHero(heroIndex + 1); startHeroAuto(); });

    let startX = 0;
    heroTrack.addEventListener('touchstart', (e) => startX = e.touches[0].clientX, { passive: true });
    heroTrack.addEventListener('touchend', (e) => {
      const dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 45) setHero(heroIndex + (dx < 0 ? 1 : -1));
      startHeroAuto();
    });

    startHeroAuto();

    const regionTabs = document.getElementById('regionTabs');
    const teamTrack = document.getElementById('teamTrack');

    function renderTeam(region) {
      teamTrack.innerHTML = '';
      teamData[region].forEach(m => {
        const card = document.createElement('article');
        card.className = 'team-card';
        card.innerHTML = `
          <div class="team-photo"><img src="${m.image}" alt="${m.name}, ${m.title}" /></div>
          <div class="team-content">
            <blockquote>“${m.quote}”</blockquote>
            <p><strong>${m.name}</strong> · ${m.title}</p>
            <p>${m.office} Studio</p>
            <a href="#footer">Contact ${m.office}</a>
          </div>
        `;
        teamTrack.appendChild(card);
      });
      teamTrack.scrollTo({ left: 0, behavior: 'smooth' });
    }

    Object.keys(teamData).forEach((region, i) => {
      const tab = document.createElement('button');
      tab.className = 'region-tab' + (i === 0 ? ' active' : '');
      tab.textContent = region;
      tab.addEventListener('click', () => {
        [...regionTabs.children].forEach(x => x.classList.remove('active'));
        tab.classList.add('active');
        renderTeam(region);
      });
      regionTabs.appendChild(tab);
    });
    renderTeam('North America');

    const workRow = document.getElementById('workRow');
    workProjects.forEach((title, i) => {
      const card = document.createElement('article');
      card.className = 'work-card';
      card.innerHTML = `
        <div class="card-media"><img src="https://images.unsplash.com/photo-${1500000000000 + (i+1)*1456789}?auto=format&fit=crop&w=1100&q=70" alt="${title}"/></div>
        <div class="card-body"><h3>${title}</h3><p>Enterprise case study · Experience reinvention</p></div>
      `;
      workRow.appendChild(card);
    });

    const insightsRow = document.getElementById('insightsRow');
    insights.forEach((title, i) => {
      const card = document.createElement('article');
      card.className = 'insight-card';
      card.innerHTML = `
        <div class="card-media"><img src="https://images.unsplash.com/photo-${1490000000000 + (i+3)*987654}?auto=format&fit=crop&w=1100&q=70" alt="${title}"/></div>
        <div class="card-body"><h3>${title}</h3><p>Podcast / Article / Report</p></div>
      `;
      insightsRow.appendChild(card);
    });

    const principlesGrid = document.getElementById('principlesGrid');
    principles.forEach(item => {
      const panel = document.createElement('article');
      panel.className = 'panel';
      panel.innerHTML = `<h3>${item}</h3><p>We build durable change by combining strategic thinking, design excellence, and responsible innovation.</p>`;
      principlesGrid.appendChild(panel);
    });

    const howGrid = document.getElementById('howGrid');
    howWeWork.forEach(step => {
      const panel = document.createElement('article');
      panel.className = 'panel';
      panel.innerHTML = `<h3>${step.t}</h3><p>${step.d}</p>`;
