        <div class="card-body"><h3>${title}</h3><p>Enterprise case study · Experience reinvention</p></div>
      `;
      workRow.appendChild(card);
    });

    const insightsRow = document.getElementById('insightsRow');
    insights.forEach((title, i) => {
      const card = document.createElement('article');
      card.className = 'insight-card';
      card.innerHTML = `
        <div class="card-media"><img src="https://images.unsplash.com/photo-${1490000000000 + (i+3)*987654}?auto=format&fit=crop&w=1100&q=70" alt="${title}"/></div>
