    howWeWork.forEach(step => {
      const panel = document.createElement('article');
      panel.className = 'panel';
      panel.innerHTML = `<h3>${step.t}</h3><p>${step.d}</p>`;
      howGrid.appendChild(panel);
    });

    const langBtn = document.getElementById('langBtn');
    const langMenu = document.getElementById('langMenu');
    langBtn.addEventListener('click', () => langMenu.classList.toggle('open'));
    langMenu.querySelectorAll('button').forEach(btn => {
      btn.addEventListener('click', () => {
        langBtn.textContent = `${btn.dataset.lang} ▾`;
        langMenu.classList.remove('open');
      });
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.lang-wrap')) langMenu.classList.remove('open');
    });

    const cookieBanner = document.getElementById('cookieBanner');
    ['acceptCookies', 'declineCookies', 'manageCookies'].forEach(id => {
      document.getElementById(id).addEventListener('click', () => cookieBanner.classList.add('hidden'));
    });

    const menuToggle = document.getElementById('menuToggle');
    const navLinks = document.getElementById('navLinks');
    menuToggle.addEventListener('click', () => navLinks.classList.toggle('open'));
    navLinks.querySelectorAll('a').forEach(a => a.addEventListener('click', () => navLinks.classList.remove('open')));
  </script>
